CREATE OR REPLACE FUNCTION public.student_balances(_student uuid) RETURNS TABLE(fee_type_id uuid,name text,account text,due numeric,paid numeric,balance numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
WITH amounts AS (SELECT f.id,f.name,f.account,
coalesce((SELECT sum(i.amount) FROM student_invoices i WHERE i.student_id=s.id AND i.fee_type_id=f.id),0) + coalesce((SELECT a.amount FROM student_fee_arrears a WHERE a.student_id=s.id AND a.fee_type_id=f.id),0) d,
coalesce((SELECT sum(a.amount) FROM payment_allocations a JOIN payment_receipts r ON r.id=a.receipt_id WHERE a.student_id=s.id AND a.fee_type_id=f.id AND NOT r.voided),0) p
FROM students s JOIN schools sc ON sc.id=s.school_id JOIN fee_types f ON f.school_id=s.school_id WHERE s.id=_student AND public.has_perm(s.school_id,'view') AND ((f.active AND f.year=sc.current_year AND f.term=sc.current_term AND (cardinality(f.applies_to)=0 OR s.grade=ANY(f.applies_to)) AND (NOT f.boarding_only OR s.boarding)) OR EXISTS(SELECT 1 FROM student_fee_arrears a WHERE a.student_id=s.id AND a.fee_type_id=f.id) OR EXISTS(SELECT 1 FROM student_invoices i WHERE i.student_id=s.id AND i.fee_type_id=f.id) OR EXISTS(SELECT 1 FROM payment_allocations a WHERE a.student_id=s.id AND a.fee_type_id=f.id))) SELECT id,name,account,d,p,d-p FROM amounts ORDER BY name $$;

CREATE OR REPLACE FUNCTION public.import_students(_school uuid,_rows jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _r jsonb; _n integer:=0; BEGIN IF NOT coalesce(public.has_perm(_school,'students'),false) THEN RAISE EXCEPTION 'Not permitted'; END IF; IF jsonb_typeof(_rows) IS DISTINCT FROM 'array' OR jsonb_array_length(_rows)>2000 THEN RAISE EXCEPTION 'Invalid import'; END IF; FOR _r IN SELECT * FROM jsonb_array_elements(_rows) LOOP IF jsonb_array_length(coalesce(_r->'arrears','[]'::jsonb))>0 AND NOT coalesce(public.has_perm(_school,'finance'),false) THEN RAISE EXCEPTION 'Not permitted to set arrears'; END IF; PERFORM public.enrol_student(_school,_r->'student',coalesce(_r->'arrears','[]'::jsonb)); _n:=_n+1; END LOOP; RETURN _n; END $$;
REVOKE ALL ON FUNCTION public.import_students(uuid,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.import_students(uuid,jsonb) TO authenticated,service_role;